import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"56、【旅】 艮下離上","description":"橫渠易說 - 56、【旅】 艮下離上","frontmatter":{"title":"56、【旅】 艮下離上","description":"橫渠易說 - 56、【旅】 艮下離上"},"headers":[],"relativePath":"classics/hengqu/058.md","filePath":"classics/hengqu/058.md"}'),l={name:"classics/hengqu/058.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_56、【旅】-艮下離上" tabindex="-1">56、【旅】 艮下離上 <a class="header-anchor" href="#_56、【旅】-艮下離上" aria-label="Permalink to “56、【旅】 艮下離上”">​</a></h1><h3 id="彖曰-旅小亨-柔得中乎外而順乎剛-止而麗乎明-是以小亨旅貞吉也-旅之時義大矣哉" tabindex="-1">彖曰：“旅小亨”，柔得中乎外而順乎剛，止而麗乎明，是以小亨旅貞吉也，旅之時義大矣哉! <a class="header-anchor" href="#彖曰-旅小亨-柔得中乎外而順乎剛-止而麗乎明-是以小亨旅貞吉也-旅之時義大矣哉" aria-label="Permalink to “彖曰：“旅小亨”，柔得中乎外而順乎剛，止而麗乎明，是以小亨旅貞吉也，旅之時義大矣哉!”">​</a></h3><h3 id="象曰-山上有火-旅-君子以明慎用刑而不留獄。" tabindex="-1">象曰：山上有火，旅，君子以明慎用刑而不留獄。 <a class="header-anchor" href="#象曰-山上有火-旅-君子以明慎用刑而不留獄。" aria-label="Permalink to “象曰：山上有火，旅，君子以明慎用刑而不留獄。”">​</a></h3><h3 id="初六-旅瑣瑣-斯其所取災。-象曰-旅瑣瑣-志窮災也。" tabindex="-1">初六，旅瑣瑣，斯其所取災。 象曰：“旅瑣瑣”，志窮災也。 <a class="header-anchor" href="#初六-旅瑣瑣-斯其所取災。-象曰-旅瑣瑣-志窮災也。" aria-label="Permalink to “初六，旅瑣瑣，斯其所取災。 象曰：“旅瑣瑣”，志窮災也。”">​</a></h3><p>瑣瑣，不能致命遂志，身窮而志卑也，冗細其所為，取災之道也。</p><h3 id="六二-旅即次-懷其資-得童僕-貞。-象曰-得童僕貞-終無尤也。" tabindex="-1">六二，旅即次，懷其資，得童僕，貞。 象曰：“得童僕貞”，終無尤也。 <a class="header-anchor" href="#六二-旅即次-懷其資-得童僕-貞。-象曰-得童僕貞-終無尤也。" aria-label="Permalink to “六二，旅即次，懷其資，得童僕，貞。 象曰：“得童僕貞”，終無尤也。”">​</a></h3><p>居得位，即次之義，得三之助，故曰“懷其資”，下有一陰，無所繫累，故曰“得童僕貞”。</p><h3 id="九三-旅焚其次-喪其童僕-貞厲。-象曰-旅焚其次-亦以傷矣-以旅與下-其義喪也。" tabindex="-1">九三，旅焚其次，喪其童僕，貞厲。 象曰：“旅焚其次”，亦以傷矣，以旅與下，其義喪也。 <a class="header-anchor" href="#九三-旅焚其次-喪其童僕-貞厲。-象曰-旅焚其次-亦以傷矣-以旅與下-其義喪也。" aria-label="Permalink to “九三，旅焚其次，喪其童僕，貞厲。 象曰：“旅焚其次”，亦以傷矣，以旅與下，其義喪也。”">​</a></h3><p>以陽居陽，其志亢也，旅而驕亢，焚次宜也。下比二陰，喪其御下之正，危厲之道。</p><h3 id="九四-旅於處-得其資斧-我心不快。-象曰-旅於處-未得位也。-得其資斧-心未快也。" tabindex="-1">九四，旅於處，得其資斧，我心不快。 象曰：“旅於處”，未得位也。“得其資斧”，心未快也。 <a class="header-anchor" href="#九四-旅於處-得其資斧-我心不快。-象曰-旅於處-未得位也。-得其資斧-心未快也。" aria-label="Permalink to “九四，旅於處，得其資斧，我心不快。 象曰：“旅於處”，未得位也。“得其資斧”，心未快也。”">​</a></h3><p>以陽居陰，旅於處也。所應在初，初為瑣瑣，志窮卑下，不能大助於己，但得其資斧之用而已，志未有得，故其心不快。</p><h3 id="六五-射雉一矢亡-終以譽命。-象曰-終以譽命-上逮也。" tabindex="-1">六五，射雉一矢亡，終以譽命。 象曰：“終以譽命”，上逮也。 <a class="header-anchor" href="#六五-射雉一矢亡-終以譽命。-象曰-終以譽命-上逮也。" aria-label="Permalink to “六五，射雉一矢亡，終以譽命。 象曰：“終以譽命”，上逮也。”">​</a></h3><p>四處陰應下，堅介難致，雉之象也，以力致之，徒喪其矢。喪矢，喪其直也，文明居中，必不失其直，當終得譽美。</p><h3 id="上九-鳥焚其巢-旅人先笑後號啕-喪牛於易-兇。-象曰-以旅在上-其義焚也-喪牛於易-終莫之聞也。" tabindex="-1">上九，鳥焚其巢，旅人先笑後號啕，喪牛於易，兇。 象曰：以旅在上，其義焚也；“喪牛於易”，終莫之聞也。 <a class="header-anchor" href="#上九-鳥焚其巢-旅人先笑後號啕-喪牛於易-兇。-象曰-以旅在上-其義焚也-喪牛於易-終莫之聞也。" aria-label="Permalink to “上九，鳥焚其巢，旅人先笑後號啕，喪牛於易，兇。 象曰：以旅在上，其義焚也；“喪牛於易”，終莫之聞也。”">​</a></h3><p>以陽極上，旅而驕肆者也，失柔順之正，故曰“喪牛於易”。易，肆也，肆怒而忤物，雖有兇危，其誰告之，故曰“終莫之聞”也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
